package com.nexustools.genericui.style.css

/**
 * Interface implemented by build-time precompiled SASS/SCSS stylesheet objects generated by
 * the GenericUI Gradle plugin (`compileGenericUiSass`).
 *
 * Precompiled stylesheets bypass runtime SASS/CSS string parsing on native/desktop/mobile targets
 * by holding pre-sorted [CssRule] and strongly-typed [CompiledStyleRule] tables directly in Kotlin code,
 * while also exposing [rawCss] and [cssResourcePath] so the `:web` backend can inject a native
 * `<style>` or `<link rel="stylesheet">` element with zero runtime overhead.
 */
interface PrecompiledStyleSheet {
    /**
     * Logical name of the stylesheet (e.g., `"MainTheme"`).
     */
    val name: String

    /**
     * Pre-parsed and specificity-sorted [CssStyleSheet] ready for immediate O(1) style lookups.
     */
    val styleSheet: CssStyleSheet

    /**
     * Compiled standard CSS text (used by `:web` to inject a `<style>` tag directly into `<head>`).
     */
    val rawCss: String

    /**
     * Relative resource path to the compiled `.css` asset in the bundle (e.g., `"/styles/main.css"`).
     */
    val cssResourcePath: String
        get() = "/styles/$name.css"

    /**
     * Source or resource path identifier for this stylesheet.
     */
    val sourcePath: String
        get() = cssResourcePath

    /**
     * Strongly-typed precompiled style rules (`CompiledStyleRule`) generated at build time.
     */
    val compiledRules: List<CompiledStyleRule>
        get() = emptyList()

    /**
     * Optional hook invoked when this stylesheet is attached to an [com.nexustools.genericui.component.shell.IApplication].
     */
    fun applyTo(application: com.nexustools.genericui.component.shell.IApplication) {}
}
